			&
			=
			\begin{bmatrix}
				0 & 0
				\\
				-E_{\textup{c}} & 0
			\end{bmatrix}
			,
			\\
			N_{21}
			&
			=
			\begin{bmatrix}
				0 & -E_{\textup{c}}^*
